+package s2
+
+import (
+	"errors"
+	"fmt"
+	"io"
+	"math"
+	"sync/atomic"
+)
+
+// shapeIndexEncodingVersion is the version of the ShapeIndex encoding format.
+const shapeIndexEncodingVersion = uint8(1)
+
+// shapeIndexShapeTag identifies the concrete type of a shape within an
+// encoded ShapeIndex.
+type shapeIndexShapeTag uint8
+
+const (
+	shapeIndexTagPolygon shapeIndexShapeTag = iota + 1
+	shapeIndexTagLoop
+	shapeIndexTagPolyline
+	shapeIndexTagPointVector
+	shapeIndexTagLaxPolyline
+	shapeIndexTagLaxLoop
+	shapeIndexTagLaxPolygon
+)
+
+// maxDecodeCapacity bounds the capacity preallocated for any slice while
+// decoding. Slices larger than this grow as elements are actually read, so a
+// corrupted count cannot trigger a huge allocation before the input runs out.
+const maxDecodeCapacity = 1 << 12
+
+// Encode encodes the ShapeIndex, including all of its shapes and the full
+// spatial cell structure. Any pending updates are applied first. Shape IDs
+// are preserved, so a decoded index refers to its shapes by the same IDs.
+//
+// Only the built-in Shape types (Polygon, Loop, Polyline, PointVector,
+// LaxPolyline, LaxLoop and LaxPolygon) are supported.
+func (s *ShapeIndex) Encode(w io.Writer) error {
+	s.maybeApplyUpdates()
+	s.mu.RLock()
+	defer s.mu.RUnlock()
+
+	e := &encoder{w: w}
+	s.encode(e)
+	return e.err
+}
+
+func (s *ShapeIndex) encode(e *encoder) {
+	// Validate all shapes before writing anything.
+	for id := int32(0); id < s.nextID; id++ {
+		if shape, ok := s.shapes[id]; ok {
+			if _, err := shapeIndexTagFor(shape); err != nil {
+				e.err = fmt.Errorf("shape %d: %v", id, err)
+				return
+			}
+		}
+	}
+
+	e.writeUint8(shapeIndexEncodingVersion)
+	e.writeUvarint(uint64(s.maxEdgesPerCell))
+	e.writeUvarint(uint64(s.nextID))
+	e.writeUvarint(uint64(len(s.shapes)))
+	for id := int32(0); id < s.nextID; id++ {
+		shape, ok := s.shapes[id]
+		if !ok {
+			continue
+		}
+		tag, _ := shapeIndexTagFor(shape)
+		e.writeUvarint(uint64(id))
+		e.writeUint8(uint8(tag))
+		encodeIndexShape(e, shape)
+	}
+
+	e.writeUvarint(uint64(len(s.cells)))
+	for _, id := range s.cells {
+		e.writeUint64(uint64(id))
+		// Skip clipped shapes for shapes that are no longer in the index.
+		var clipped []*clippedShape
+		for _, c := range s.cellMap[id].shapes {
+			if _, ok := s.shapes[c.shapeID]; ok {
+				clipped = append(clipped, c)
+			}
+		}
+		e.writeUvarint(uint64(len(clipped)))
+		for _, c := range clipped {
+			e.writeUvarint(uint64(c.shapeID))
+			e.writeBool(c.containsCenter)
+			e.writeUvarint(uint64(len(c.edges)))
+			for _, edge := range c.edges {
+				e.writeUvarint(uint64(edge))
+			}
+		}
+	}
+}
+
+func shapeIndexTagFor(shape Shape) (shapeIndexShapeTag, error) {
+	switch shape.(type) {
+	case *Polygon:
+		return shapeIndexTagPolygon, nil
+	case *Loop:
+		return shapeIndexTagLoop, nil
+	case *Polyline:
+		return shapeIndexTagPolyline, nil
+	case *PointVector:
+		return shapeIndexTagPointVector, nil
+	case *LaxPolyline:
+		return shapeIndexTagLaxPolyline, nil
+	case *LaxLoop:
+		return shapeIndexTagLaxLoop, nil
+	case *LaxPolygon:
+		return shapeIndexTagLaxPolygon, nil
+	}
+	return 0, fmt.Errorf("unsupported shape type %T", shape)
+}
+
+func encodeIndexShape(e *encoder, shape Shape) {
+	switch sh := shape.(type) {
+	case *Polygon:
+		e.writeBool(sh.hasHoles)
+		e.writeUvarint(uint64(len(sh.loops)))
+		for _, l := range sh.loops {
+			encodeIndexLoop(e, l)
+		}
+		sh.bound.encode(e)
+	case *Loop:
+		encodeIndexLoop(e, sh)
+	case *Polyline:
+		encodeIndexPoints(e, *sh)
+	case *PointVector:
+		encodeIndexPoints(e, *sh)
+	case *LaxPolyline:
+		encodeIndexPoints(e, sh.vertices)
+	case *LaxLoop:
+		encodeIndexPoints(e, sh.vertices[:sh.numVertices])
+	case *LaxPolygon:
+		e.writeUvarint(uint64(sh.numLoops))
+		for i := 0; i < sh.numLoops; i++ {
+			n := sh.numLoopVertices(i)
+			e.writeUvarint(uint64(n))
+			for j := 0; j < n; j++ {
+				encodeIndexPoint(e, sh.loopVertex(i, j))
+			}
+		}
+	}
+}
+
+func encodeIndexLoop(e *encoder, l *Loop) {
+	encodeIndexPoints(e, l.vertices)
+	e.writeBool(l.originInside)
+	e.writeInt32(int32(l.depth))
+	l.bound.encode(e)
+}
+
+func encodeIndexPoints(e *encoder, pts []Point) {
+	e.writeUvarint(uint64(len(pts)))
+	for _, p := range pts {
+		encodeIndexPoint(e, p)
+	}
+}
+
+func encodeIndexPoint(e *encoder, p Point) {
+	e.writeFloat64(p.X)
+	e.writeFloat64(p.Y)
+	e.writeFloat64(p.Z)
+}
+
+// Decode decodes a ShapeIndex previously written by Encode, replacing the
+// current contents of s. The decoded index is fully built: queries and
+// iteration work without calling Build. Malformed input results in an
+// error, in which case s is left unchanged.
+func (s *ShapeIndex) Decode(r io.Reader) (err error) {
+	defer func() {
+		// Defense in depth: never let malformed input crash the caller.
+		if p := recover(); p != nil {
+			err = fmt.Errorf("s2: malformed ShapeIndex encoding: %v", p)
+		}
+	}()
+
+	d := &decoder{r: asByteReader(r)}
+	dec := shapeIndexDecoder{d: d}
+	dec.decode()
+	if d.err != nil {
+		if errors.Is(d.err, io.EOF) {
+			d.err = io.ErrUnexpectedEOF
+		}
+		return d.err
+	}
+
+	s.mu.Lock()
+	defer s.mu.Unlock()
+	s.maxEdgesPerCell = dec.maxEdgesPerCell
+	s.nextID = dec.nextID
+	s.shapes = dec.shapes
+	s.cells = dec.cells
+	s.cellMap = dec.cellMap
+	s.pendingAdditionsPos = dec.nextID
+	s.pendingRemovals = nil
+	atomic.StoreInt32(&s.status, fresh)
+	return nil
+}
+
+type shapeIndexDecoder struct {
+	d *decoder
+
+	maxEdgesPerCell int
+	nextID          int32
+	shapes          map[int32]Shape
+	cells           []CellID
+	cellMap         map[CellID]*ShapeIndexCell
+}
+
+func (sd *shapeIndexDecoder) fail(format string, args ...any) {
+	if sd.d.err == nil {
+		sd.d.err = fmt.Errorf("s2: decoding ShapeIndex: "+format, args...)
+	}
+}
+
+func (sd *shapeIndexDecoder) ok() bool { return sd.d.err == nil }
+
+// readCount reads a uvarint element count and verifies it is at most limit.
+func (sd *shapeIndexDecoder) readCount(what string, limit uint64) int {
+	n := sd.d.readUvarint()
+	if !sd.ok() {
+		return 0
+	}
+	if n > limit {
+		sd.fail("too many %s (%d; max is %d)", what, n, limit)
+		return 0
+	}
+	return int(n)
+}
+
+func (sd *shapeIndexDecoder) readBool() bool {
+	b := sd.d.readUint8()
+	if sd.ok() && b > 1 {
+		sd.fail("invalid boolean value %d", b)
+	}
+	return b == 1
+}
+
+func (sd *shapeIndexDecoder) decode() {
+	d := sd.d
+	version := d.readUint8()
+	if !sd.ok() {
+		return
+	}
+	if version != shapeIndexEncodingVersion {
+		sd.fail("unsupported version %d", version)
+		return
+	}
+
+	sd.maxEdgesPerCell = sd.readCount("max edges per cell", math.MaxInt32)
+	sd.nextID = int32(sd.readCount("shape IDs", math.MaxInt32))
+	numShapes := sd.readCount("shapes", uint64(sd.nextID))
+	if !sd.ok() {
+		return
+	}
+
+	sd.shapes = make(map[int32]Shape, min(numShapes, maxDecodeCapacity))
+	prevID := int64(-1)
+	for i := 0; i < numShapes && sd.ok(); i++ {
+		id := d.readUvarint()
+		if !sd.ok() {
+			return
+		}
+		if int64(id) <= prevID || id >= uint64(sd.nextID) {
+			sd.fail("invalid shape ID %d", id)
+			return
+		}
+		prevID = int64(id)
+		shape := sd.decodeShape(shapeIndexShapeTag(d.readUint8()))
+		if !sd.ok() {
+			return
+		}
+		sd.shapes[int32(id)] = shape
+	}
+
+	numCells := sd.readCount("cells", math.MaxInt)
+	if !sd.ok() {
+		return
+	}
+	sd.cells = make([]CellID, 0, min(numCells, maxDecodeCapacity))
+	sd.cellMap = make(map[CellID]*ShapeIndexCell, min(numCells, maxDecodeCapacity))
+	for i := 0; i < numCells && sd.ok(); i++ {
+		sd.decodeCell()
+	}
+}
+
+func (sd *shapeIndexDecoder) decodeCell() {
+	d := sd.d
+	id := CellID(d.readUint64())
+	if !sd.ok() {
+		return
+	}
+	if !id.IsValid() {
+		sd.fail("invalid cell ID %v", uint64(id))
+		return
+	}
+	if n := len(sd.cells); n > 0 && id.RangeMin() <= sd.cells[n-1].RangeMax() {
+		sd.fail("cell %v is out of order or overlaps the previous cell", id)
+		return
+	}
+
+	numClipped := sd.readCount("shapes in cell", uint64(len(sd.shapes)))
+	if !sd.ok() {
+		return
+	}
+	cell := &ShapeIndexCell{shapes: make([]*clippedShape, 0, min(numClipped, maxDecodeCapacity))}
+	prevShapeID := int64(-1)
+	for j := 0; j < numClipped; j++ {
+		shapeID := d.readUvarint()
+		if !sd.ok() {
+			return
+		}
+		shape, found := sd.shapes[int32(shapeID)]
+		if shapeID > math.MaxInt32 || int64(shapeID) <= prevShapeID || !found {
+			sd.fail("invalid shape ID %d in cell %v", shapeID, id)
+			return
+		}
+		prevShapeID = int64(shapeID)
+
+		containsCenter := sd.readBool()
+		shapeEdges := shape.NumEdges()
+		numEdges := sd.readCount("edges in clipped shape", uint64(shapeEdges))
+		if !sd.ok() {
+			return
+		}
+		c := &clippedShape{
+			shapeID:        int32(shapeID),
+			containsCenter: containsCenter,
+			edges:          make([]int, 0, min(numEdges, maxDecodeCapacity)),
+		}
+		prevEdge := int64(-1)
+		for k := 0; k < numEdges; k++ {
+			edge := d.readUvarint()
+			if !sd.ok() {
+				return
+			}
+			if int64(edge) <= prevEdge || edge >= uint64(shapeEdges) {
+				sd.fail("invalid edge ID %d for shape %d in cell %v", edge, shapeID, id)
+				return
+			}
+			prevEdge = int64(edge)
+			c.edges = append(c.edges, int(edge))
+		}
+		cell.shapes = append(cell.shapes, c)
+	}
+
+	sd.cells = append(sd.cells, id)
+	sd.cellMap[id] = cell
+}
+
+func (sd *shapeIndexDecoder) decodeShape(tag shapeIndexShapeTag) Shape {
+	if !sd.ok() {
+		return nil
+	}
+	switch tag {
+	case shapeIndexTagPolygon:
+		return sd.decodePolygon()
+	case shapeIndexTagLoop:
+		return sd.decodeLoop()
+	case shapeIndexTagPolyline:
+		p := Polyline(sd.decodePoints())
+		return &p
+	case shapeIndexTagPointVector:
+		p := PointVector(sd.decodePoints())
+		return &p
+	case shapeIndexTagLaxPolyline:
+		return &LaxPolyline{vertices: sd.decodePoints()}
+	case shapeIndexTagLaxLoop:
+		pts := sd.decodePoints()
+		return &LaxLoop{numVertices: len(pts), vertices: pts}
+	case shapeIndexTagLaxPolygon:
+		numLoops := sd.readCount("loops", maxEncodedLoops)
+		loops := make([][]Point, 0, min(numLoops, maxDecodeCapacity))
+		for i := 0; i < numLoops && sd.ok(); i++ {
+			loops = append(loops, sd.decodePoints())
+		}
+		if !sd.ok() {
+			return nil
+		}
+		return LaxPolygonFromPoints(loops)
+	}
+	sd.fail("unknown shape type tag %d", tag)
+	return nil
+}
+
+func (sd *shapeIndexDecoder) decodePolygon() *Polygon {
+	p := &Polygon{}
+	p.hasHoles = sd.readBool()
+	numLoops := sd.readCount("loops", maxEncodedLoops)
+	p.loops = make([]*Loop, 0, min(numLoops, maxDecodeCapacity))
+	for i := 0; i < numLoops && sd.ok(); i++ {
+		l := sd.decodeLoop()
+		if !sd.ok() {
+			return nil
+		}
+		p.loops = append(p.loops, l)
+		p.numVertices += len(l.vertices)
+	}
+	sd.decodeRect(&p.bound)
+	if !sd.ok() {
+		return nil
+	}
+	p.subregionBound = ExpandForSubregions(p.bound)
+	p.initEdgesAndIndex()
+	return p
+}
+
+func (sd *shapeIndexDecoder) decodeLoop() *Loop {
+	l := &Loop{}
+	l.vertices = sd.decodePoints()
+	l.originInside = sd.readBool()
+	l.depth = int(int32(sd.d.readUint32()))
+	sd.decodeRect(&l.bound)
+	if !sd.ok() {
+		return nil
+	}
+	l.subregionBound = ExpandForSubregions(l.bound)
+	l.index = NewShapeIndex()
+	l.index.Add(l)
+	return l
+}
+
+func (sd *shapeIndexDecoder) decodeRect(r *Rect) {
+	r.decode(sd.d)
+	if sd.ok() && !(isFinite(r.Lat.Lo) && isFinite(r.Lat.Hi) && isFinite(r.Lng.Lo) && isFinite(r.Lng.Hi)) {
+		sd.fail("invalid bound %v", *r)
+	}
+}
+
+func (sd *shapeIndexDecoder) decodePoints() []Point {
+	n := sd.readCount("vertices", maxEncodedVertices)
+	if !sd.ok() {
+		return nil
+	}
+	pts := make([]Point, 0, min(n, maxDecodeCapacity))
+	for i := 0; i < n; i++ {
+		var p Point
+		p.X = sd.d.readFloat64()
+		p.Y = sd.d.readFloat64()
+		p.Z = sd.d.readFloat64()
+		if !sd.ok() {
+			return nil
+		}
+		if !isFinite(p.X) || !isFinite(p.Y) || !isFinite(p.Z) {
+			sd.fail("invalid vertex %v", p)
+			return nil
+		}
+		pts = append(pts, p)
+	}
+	return pts
+}
+
+func isFinite(f float64) bool {
+	return !math.IsNaN(f) && !math.IsInf(f, 0)
+}
